export const surveyReceiptSchema = z.object({ answeredAt: z.string() });
export type SurveyReceipt = z.output<typeof surveyReceiptSchema>;

/** The copy of the member screens. */
export const SURVEY_TEXT = {
  thanks: "Thanks for your answers.",
  retired: "This survey is closed.",
  answered: "You already answered this survey.",
} as const;

const enc = encodeURIComponent;

export function surveysApi(api: Client) {
  return {
    get: (id: string): Promise<ApiResult<MemberSurvey>> => api.get(`/v1/me/surveys/${enc(id)}`, { schema: memberSurveySchema }),
    respond: (id: string, body: z.input<typeof surveyResponseSchema>): Promise<ApiResult<SurveyReceipt>> =>
      api.post(`/v1/me/surveys/${enc(id)}/response`, body, { schema: surveyReceiptSchema }),
  };
}
